MAP
    NAME "SS_MAP_MCIR_SUBSECTORES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'wfs_getfeature_formatlist' 'gml,geojson'
            "wfs_enable_request" "*"
            "gml_featureid" "gid"
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_subsectores.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_MCIR_SUBSECTORES"
        CONNECTIONTYPE POSTGIS
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from subsectores using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELITEM "nombre"
        CLASS
            NAME "Subsector"
            STYLE
				WIDTH 5
				OUTLINECOLOR 230 158 180
			END #STYLE
            LABEL
                TYPE TRUETYPE
                SIZE 19
                COLOR 0 0 0
                PARTIALS FALSE      
                FONT ARIAL
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP